def longest_increasing_path(m):
    R_, C = len(m), len(m[0]); order = sorted((m[r][c], r, c) for r in range(R_) for c in range(C)); best = [[1] * C for _ in range(R_)]
    for v, r, c in reversed(order):
        for rr, cc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= rr < R_ and 0 <= cc < C and m[rr][cc] > v and best[rr][cc] + 1 > best[r][c]: best[r][c] = best[rr][cc] + 1
    return max(max(row) for row in best)

