int longestIncreasingPath(vector<vector<int>>& m) {
    int R = m.size(), C = m[0].size(); vector<array<int,3>> o; for (int r = 0; r < R; r++) for (int c = 0; c < C; c++) o.push_back({m[r][c], r, c}); sort(o.rbegin(), o.rend());
    vector<vector<int>> b(R, vector<int>(C, 1)); int d[5] = {1, 0, -1, 0, 1}, best = 1;
    for (auto& [v, r, c] : o) { for (int k = 0; k < 4; k++) { int rr = r + d[k], cc = c + d[k+1]; if (rr >= 0 && rr < R && cc >= 0 && cc < C && m[rr][cc] > v) b[r][c] = max(b[r][c], b[rr][cc] + 1); } best = max(best, b[r][c]); }
    return best;
}
